const items = $input.all();

return items.map(item => {
  const email = item.json;

  // Template de réponse pour support technique
  const reponse = `Bonjour,

Nous avons bien reçu votre demande de support technique concernant : "${email.subject}".

Notre équipe technique va analyser votre demande et vous reviendra dans les plus brefs délais avec une solution.

Pour accélérer le traitement de votre demande, vous pouvez nous fournir :
- Une description détaillée du problème
- Des captures d'écran si applicable
- Les étapes pour reproduire le problème

Nous vous remercions de votre patience.

Cordialement,
L'équipe Support
`;

  return {
    json: {
      ...email,
      responseType: 'support_technique',
      responseBody: reponse,
      priority: email.confidence === 'élevée' ? 'haute' : 'normale',
      shouldSendAuto: email.categoryScore > 0.7 // Envoi auto si confiance > 70%
    }
  };
});

